import { promises as fs } from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";

export class BookStore {
  constructor(filePath) {
    this.filePath = filePath;
    this.books = [];
  }

  async load() {
    try {
      const raw = await fs.readFile(this.filePath, "utf8");
      const parsed = JSON.parse(raw);
      this.books = Array.isArray(parsed) ? parsed : [];
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      this.books = [];
    }
    return this;
  }

  async save() {
    await fs.mkdir(path.dirname(this.filePath), { recursive: true });
    // Write to a temp file and rename so a crash mid-write can't leave a
    // half-written books.json behind.
    const tmp = `${this.filePath}.${process.pid}.tmp`;
    await fs.writeFile(tmp, JSON.stringify(this.books, null, 2) + "\n");
    await fs.rename(tmp, this.filePath);
  }

  all() {
    return [...this.books];
  }

  reading() {
    return this.books.filter((b) => !b.finishedAt);
  }

  finished() {
    return this.books
      .filter((b) => b.finishedAt)
      .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
  }

  get(id) {
    return this.books.find((b) => b.id === id) ?? null;
  }

  async add({ title, author, notes = "" }) {
    title = String(title ?? "").trim();
    author = String(author ?? "").trim();
    notes = String(notes ?? "").trim();
    if (!title) throw new ValidationError("Title is required.");
    if (!author) throw new ValidationError("Author is required.");

    const book = {
      id: newId(this.books),
      title,
      author,
      notes,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    this.books.push(book);
    await this.save();
    return book;
  }

  async finish(id) {
    const book = this.get(id);
    if (!book) return null;
    if (!book.finishedAt) {
      book.finishedAt = new Date().toISOString();
      await this.save();
    }
    return book;
  }

  async updateNotes(id, notes) {
    const book = this.get(id);
    if (!book) return null;
    book.notes = String(notes ?? "").trim();
    await this.save();
    return book;
  }
}

export class ValidationError extends Error {}

function newId(existing) {
  let id;
  do {
    id = randomBytes(4).toString("hex");
  } while (existing.some((b) => b.id === id));
  return id;
}

