import http from "node:http";
import { ValidationError } from "./store.mjs";

const MAX_BODY_BYTES = 64 * 1024;

export function createApp(store) {
  return http.createServer(async (req, res) => {
    try {
      await route(store, req, res);
    } catch (err) {
      console.error(err);
      sendHtml(res, 500, page("Something went wrong", `<p class="error">Something went wrong. Please try again.</p>`));
    }
  });
}

async function route(store, req, res) {
  const url = new URL(req.url, "http://localhost");
  const parts = url.pathname.split("/").filter(Boolean);

  if (req.method === "GET" && parts.length === 0) {
    return sendHtml(res, 200, renderHome(store, { error: url.searchParams.get("error") }));
  }

  if (parts[0] === "books") {
    if (req.method === "POST" && parts.length === 1) {
      const form = await readForm(req);
      try {
        const book = await store.add(form);
        return redirect(res, `/books/${book.id}`);
      } catch (err) {
        if (err instanceof ValidationError) {
          return redirect(res, `/?error=${encodeURIComponent(err.message)}`);
        }
        throw err;
      }
    }

    if (parts.length >= 2) {
      const book = store.get(parts[1]);
      if (!book) return notFound(res);

      if (req.method === "GET" && parts.length === 2) {
        return sendHtml(res, 200, renderBook(book));
      }
      if (req.method === "POST" && parts[2] === "finish" && parts.length === 3) {
        await store.finish(book.id);
        return redirect(res, `/books/${book.id}`);
      }
      if (req.method === "POST" && parts[2] === "notes" && parts.length === 3) {
        const form = await readForm(req);
        await store.updateNotes(book.id, form.notes);
        return redirect(res, `/books/${book.id}`);
      }
    }
  }

  return notFound(res);
}

// ---- rendering ----

function renderHome(store, { error }) {
  const reading = store.reading();
  const finished = store.finished();

  return page(
    "My books",
    `
    <h1>My books</h1>

    <section>
      <h2>Currently reading</h2>
      ${reading.length ? bookList(reading) : `<p class="muted">Nothing on the go right now.</p>`}
    </section>

    <section>
      <h2>Finished</h2>
      ${finished.length ? bookList(finished) : `<p class="muted">No finished books yet.</p>`}
    </section>

    <section>
      <h2>Add a book</h2>
      ${error ? `<p class="error">${esc(error)}</p>` : ""}
      <form method="post" action="/books" class="stack">
        <label>Title <input name="title" required autocomplete="off"></label>
        <label>Author <input name="author" required autocomplete="off"></label>
        <label>Notes <textarea name="notes" rows="4"></textarea></label>
        <button type="submit">Add book</button>
      </form>
    </section>
    `,
  );
}

function bookList(books) {
  return `<ul class="books">${books
    .map(
      (b) => `<li>
        <a href="/books/${esc(b.id)}">${esc(b.title)}</a>
        <span class="muted">by ${esc(b.author)}</span>
        ${b.finishedAt ? `<span class="muted">· finished ${esc(formatDate(b.finishedAt))}</span>` : ""}
      </li>`,
    )
    .join("")}</ul>`;
}

function renderBook(book) {
  return page(
    book.title,
    `
    <p><a href="/">&larr; All books</a></p>
    <h1>${esc(book.title)}</h1>
    <p class="author">by ${esc(book.author)}</p>

    <p class="status">
      ${
        book.finishedAt
          ? `Finished ${esc(formatDate(book.finishedAt))}`
          : `Currently reading · started ${esc(formatDate(book.addedAt))}`
      }
    </p>

    ${
      book.finishedAt
        ? ""
        : `<form method="post" action="/books/${esc(book.id)}/finish">
             <button type="submit">Mark as finished</button>
           </form>`
    }

    <section>
      <h2>Notes</h2>
      <form method="post" action="/books/${esc(book.id)}/notes" class="stack">
        <textarea name="notes" rows="8" placeholder="No notes yet.">${esc(book.notes)}</textarea>
        <button type="submit" class="secondary">Save notes</button>
      </form>
    </section>
    `,
  );
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  :root { color-scheme: light dark; }
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; }
  h1 { margin-bottom: 0.25rem; }
  h2 { font-size: 1.1rem; margin: 2rem 0 0.5rem; }
  a { color: inherit; }
  .muted { opacity: 0.65; }
  .error { color: #c0392b; }
  .author { margin-top: 0; font-size: 1.1rem; }
  .status { opacity: 0.75; }
  ul.books { list-style: none; padding: 0; margin: 0; }
  ul.books li { padding: 0.4rem 0; border-bottom: 1px solid rgba(128,128,128,0.3); }
  ul.books li a { font-weight: 600; }
  .stack { display: grid; gap: 0.75rem; }
  label { display: grid; gap: 0.25rem; }
  input, textarea { font: inherit; padding: 0.4rem 0.5rem; border: 1px solid rgba(128,128,128,0.6); border-radius: 4px; background: transparent; color: inherit; }
  button { font: inherit; padding: 0.5rem 1rem; border: 0; border-radius: 4px; background: #2c6bed; color: #fff; cursor: pointer; justify-self: start; }
  button.secondary { background: transparent; color: inherit; border: 1px solid rgba(128,128,128,0.6); }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

// ---- helpers ----

function esc(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error("Request body too large"));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => {
      const params = new URLSearchParams(Buffer.concat(chunks).toString("utf8"));
      resolve(Object.fromEntries(params));
    });
    req.on("error", reject);
  });
}

function sendHtml(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notFound(res) {
  sendHtml(res, 404, page("Not found", `<p><a href="/">&larr; All books</a></p><h1>Book not found</h1>`));
}

