import { createApp } from "./src/app.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE ?? path.join(here, "data", "books.json");
const port = Number(process.env.PORT ?? 3000);

const store = await new BookStore(dataFile).load();
createApp(store).listen(port, () => {
  console.log(`Book tracker running at http://localhost:${port}`);
  console.log(`Saving books to ${dataFile}`);
});

