import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import { BookStore, ValidationError } from "../src/store.mjs";

let dir, file;

beforeEach(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), "books-"));
  file = path.join(dir, "books.json");
});

afterEach(() => fs.rm(dir, { recursive: true, force: true }));

describe("BookStore", () => {
  it("starts empty when the file does not exist", async () => {
    const store = await new BookStore(file).load();
    expect(store.all()).toEqual([]);
  });

  it("adds a book and persists it to the JSON file", async () => {
    const store = await new BookStore(file).load();
    const book = await store.add({ title: "Dune", author: "Frank Herbert", notes: "Spice." });

    expect(book.id).toMatch(/^[0-9a-f]{8}$/);
    expect(book.finishedAt).toBeNull();

    const onDisk = JSON.parse(await fs.readFile(file, "utf8"));
    expect(onDisk).toEqual([book]);
  });

  it("reloads books after a restart", async () => {
    const first = await new BookStore(file).load();
    const book = await first.add({ title: "Dune", author: "Frank Herbert" });

    const second = await new BookStore(file).load();
    expect(second.get(book.id)).toEqual(book);
  });

  it("splits books into reading and finished", async () => {
    const store = await new BookStore(file).load();
    const a = await store.add({ title: "A", author: "X" });
    const b = await store.add({ title: "B", author: "Y" });
    await store.finish(b.id);

    expect(store.reading().map((x) => x.id)).toEqual([a.id]);
    expect(store.finished().map((x) => x.id)).toEqual([b.id]);
    expect(store.get(b.id).finishedAt).toBeTruthy();
  });

  it("does not overwrite finishedAt when finished twice", async () => {
    const store = await new BookStore(file).load();
    const book = await store.add({ title: "A", author: "X" });
    const first = (await store.finish(book.id)).finishedAt;
    await new Promise((r) => setTimeout(r, 5));
    const second = (await store.finish(book.id)).finishedAt;
    expect(second).toBe(first);
  });

  it("returns null for unknown ids", async () => {
    const store = await new BookStore(file).load();
    expect(store.get("nope")).toBeNull();
    expect(await store.finish("nope")).toBeNull();
    expect(await store.updateNotes("nope", "x")).toBeNull();
  });

  it("rejects books without a title or author", async () => {
    const store = await new BookStore(file).load();
    await expect(store.add({ title: "  ", author: "X" })).rejects.toBeInstanceOf(ValidationError);
    await expect(store.add({ title: "A", author: "" })).rejects.toBeInstanceOf(ValidationError);
    expect(store.all()).toEqual([]);
  });

  it("updates notes", async () => {
    const store = await new BookStore(file).load();
    const book = await store.add({ title: "A", author: "X" });
    await store.updateNotes(book.id, "  Loved it.  ");
    expect((await new BookStore(file).load()).get(book.id).notes).toBe("Loved it.");
  });
});

