import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import { BookStore } from "../src/store.mjs";
import { createApp } from "../src/app.mjs";

let dir, store, server, base;

beforeEach(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), "books-app-"));
  store = await new BookStore(path.join(dir, "books.json")).load();
  server = createApp(store);
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((r) => server.close(r));
  await fs.rm(dir, { recursive: true, force: true });
});

const postForm = (url, fields) =>
  fetch(base + url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams(fields),
    redirect: "manual",
  });

describe("book tracker app", () => {
  it("shows empty states on the home page", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Finished");
    expect(html).toContain("Nothing on the go right now.");
    expect(html).toContain('<form method="post" action="/books"');
  });

  it("adds a book from the form and redirects to its page", async () => {
    const res = await postForm("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice." });
    expect(res.status).toBe(303);

    const location = res.headers.get("location");
    expect(location).toMatch(/^\/books\/[0-9a-f]{8}$/);

    const home = await (await fetch(base + "/")).text();
    expect(home).toContain(`href="${location}"`);
    expect(home).toContain("Dune");
  });

  it("shows title, author and notes on the book page", async () => {
    const book = await store.add({ title: "Dune", author: "Frank Herbert", notes: "Spice & sandworms" });
    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).toContain("<h1>Dune</h1>");
    expect(html).toContain("by Frank Herbert");
    expect(html).toContain("Spice &amp; sandworms");
    expect(html).toContain("Mark as finished");
  });

  it("marks a book as finished and moves it to the finished list", async () => {
    const book = await store.add({ title: "Dune", author: "Frank Herbert" });
    const res = await postForm(`/books/${book.id}/finish`, {});
    expect(res.status).toBe(303);
    expect(res.headers.get("location")).toBe(`/books/${book.id}`);

    expect(store.get(book.id).finishedAt).toBeTruthy();

    const detail = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(detail).not.toContain("Mark as finished");
    expect(detail).toMatch(/Finished \w+ \d+, \d{4}/);
  });

  it("saves notes from the book page", async () => {
    const book = await store.add({ title: "Dune", author: "Frank Herbert" });
    await postForm(`/books/${book.id}/notes`, { notes: "Great ending." });
    expect(store.get(book.id).notes).toBe("Great ending.");
  });

  it("rejects an empty title and shows the error on the home page", async () => {
    const res = await postForm("/books", { title: "", author: "Someone" });
    expect(res.status).toBe(303);
    const location = res.headers.get("location");
    expect(location).toContain("/?error=");
    const html = await (await fetch(base + location)).text();
    expect(html).toContain("Title is required.");
    expect(store.all()).toEqual([]);
  });

  it("escapes HTML in user input", async () => {
    const book = await store.add({ title: "<script>alert(1)</script>", author: "X" });
    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).not.toContain("<script>alert(1)</script>");
    expect(html).toContain("&lt;script&gt;alert(1)&lt;/script&gt;");
  });

  it("returns 404 for unknown books and routes", async () => {
    expect((await fetch(`${base}/books/deadbeef`)).status).toBe(404);
    expect((await fetch(`${base}/nope`)).status).toBe(404);
    expect((await postForm(`/books/deadbeef/finish`, {})).status).toBe(404);
  });
});

